CREATE TRIGGER events_order BEFORE INSERT ON events WHEN NEW.seq!=(SELECT COALESCE(MAX(seq),0)+1 FROM events) OR NEW.ingested_at_us<(SELECT COALESCE(MAX(ingested_at_us),0) FROM events) OR NEW.previous_hash!=COALESCE((SELECT event_hash FROM events ORDER BY seq DESC LIMIT 1),printf('%064d',0)) BEGIN SELECT RAISE(ABORT,'ledger order or chain'); END;

CREATE TRIGGER event_span_scope BEFORE INSERT ON events WHEN NEW.span_id IS NOT NULL AND NEW.run_id!=(SELECT run_id FROM spans WHERE id=NEW.span_id) BEGIN SELECT RAISE(ABORT,'cross-run span'); END;

CREATE TRIGGER span_parent_scope BEFORE INSERT ON spans WHEN NEW.parent_span_id IS NOT NULL AND (NEW.id=NEW.parent_span_id OR NEW.run_id!=(SELECT run_id FROM spans WHERE id=NEW.parent_span_id)) BEGIN SELECT RAISE(ABORT,'invalid span parent'); END;

CREATE TRIGGER attempt_limit BEFORE INSERT ON attempts WHEN NEW.attempt_no>(SELECT max_attempts FROM invocations WHERE id=NEW.invocation_id) BEGIN SELECT RAISE(ABORT,'attempt limit'); END;

CREATE TRIGGER objective_pass BEFORE INSERT ON objective_outcomes WHEN NEW.result='pass' AND COALESCE((SELECT result FROM acceptance_checks WHERE id=NEW.check_id),'unknown')!='pass' BEGIN SELECT RAISE(ABORT,'objective requires passed check'); END;

CREATE TRIGGER recovery_material_change BEFORE INSERT ON recovery_edges WHEN (SELECT strategy_hash FROM attempts WHERE id=NEW.from_attempt_id)=(SELECT strategy_hash FROM attempts WHERE id=NEW.to_attempt_id) BEGIN SELECT RAISE(ABORT,'recovery requires changed strategy'); END;

CREATE TRIGGER meta_role BEFORE INSERT ON meta_decisions WHEN (SELECT kind FROM actors WHERE id=NEW.meta_actor_id)!='meta' BEGIN SELECT RAISE(ABORT,'meta decision requires meta actor'); END;

CREATE TRIGGER lease_gate BEFORE INSERT ON agent_leases WHEN NOT EXISTS(SELECT 1 FROM meta_decisions d JOIN events e ON e.seq=NEW.event_seq WHERE d.id=NEW.decision_id AND d.approval='approved' AND d.decision='activate' AND NEW.expires_at_us<=d.expires_at_us AND e.occurred_at_us<NEW.expires_at_us AND e.occurred_at_us<d.expires_at_us AND (SELECT COUNT(*) FROM agent_leases WHERE decision_id=d.id)<d.max_agents AND (SELECT COALESCE(SUM(reserved_cost_microusd),0) FROM agent_leases WHERE decision_id=d.id)+NEW.reserved_cost_microusd<=d.budget_microusd) BEGIN SELECT RAISE(ABORT,'unapproved expired or over-budget lease'); END;

CREATE TRIGGER lease_roles BEFORE INSERT ON agent_leases WHEN (SELECT kind FROM actors WHERE id=NEW.agent_id)!='agent' OR (SELECT kind FROM actors WHERE id=NEW.swarm_id)!='swarm' BEGIN SELECT RAISE(ABORT,'invalid lease actors'); END;

CREATE TRIGGER kv_identity BEFORE INSERT ON kv_operations WHEN NEW.identity_hash!=(SELECT identity_hash FROM caches WHERE id=NEW.cache_id) BEGIN SELECT RAISE(ABORT,'cross-identity KV'); END;

CREATE TRIGGER kv_capacity BEFORE INSERT ON kv_samples WHEN NEW.used_bytes>(SELECT capacity_bytes FROM caches WHERE id=NEW.cache_id) OR NEW.used_tokens>(SELECT capacity_tokens FROM caches WHERE id=NEW.cache_id) BEGIN SELECT RAISE(ABORT,'KV exceeds capacity'); END;

CREATE TRIGGER atom_revision_scope BEFORE INSERT ON atom_operations WHEN NEW.atom_id!=(SELECT atom_id FROM atom_revisions WHERE id=NEW.revision_id) BEGIN SELECT RAISE(ABORT,'atom revision mismatch'); END;

CREATE TRIGGER atom_judge_gate BEFORE INSERT ON atom_revisions WHEN COALESCE((SELECT result FROM acceptance_checks WHERE id=NEW.judge_check_id),'unknown')!='pass' BEGIN SELECT RAISE(ABORT,'atom requires passed judge'); END;

CREATE TRIGGER edge_graph_scope BEFORE INSERT ON graph_edges WHEN NEW.graph_id!=(SELECT graph_id FROM graph_nodes WHERE id=NEW.source_id) OR NEW.graph_id!=(SELECT graph_id FROM graph_nodes WHERE id=NEW.target_id) BEGIN SELECT RAISE(ABORT,'cross-graph edge'); END;

CREATE TRIGGER edge_dag_cycle BEFORE INSERT ON graph_edges WHEN (SELECT kind FROM graph_versions WHERE id=NEW.graph_id) IN('dag','capability') AND EXISTS(WITH RECURSIVE reachable(id) AS (SELECT NEW.target_id UNION SELECT e.target_id FROM graph_edges e JOIN reachable r ON e.source_id=r.id WHERE e.graph_id=NEW.graph_id) SELECT 1 FROM reachable WHERE id=NEW.source_id) BEGIN SELECT RAISE(ABORT,'DAG cycle'); END;

CREATE TRIGGER invocation_phase_status BEFORE INSERT ON invocation_events WHEN NOT ((NEW.phase='requested' AND NEW.status IN('pending','denied','unknown')) OR (NEW.phase='dispatched' AND NEW.status IN('pending','running','unknown')) OR (NEW.phase='started' AND NEW.status='running') OR (NEW.phase='completed' AND NEW.status IN('succeeded','failed','cancelled','timed_out','denied','unknown'))) BEGIN SELECT RAISE(ABORT,'phase status mismatch'); END;

CREATE TRIGGER invocation_success_started BEFORE INSERT ON invocation_events WHEN NEW.status='succeeded' AND NOT EXISTS(SELECT 1 FROM invocation_events WHERE attempt_id=NEW.attempt_id AND phase='started') BEGIN SELECT RAISE(ABORT,'success requires observed execution'); END;

CREATE TRIGGER invocation_scope BEFORE INSERT ON invocation_events WHEN (SELECT run_id FROM events WHERE seq=NEW.event_seq)!=(SELECT s.run_id FROM attempts a JOIN invocations i ON i.id=a.invocation_id JOIN spans s ON s.id=i.span_id WHERE a.id=NEW.attempt_id) BEGIN SELECT RAISE(ABORT,'cross-run invocation'); END;

CREATE TRIGGER check_attempt_scope BEFORE INSERT ON acceptance_checks WHEN NEW.attempt_id IS NOT NULL AND (SELECT run_id FROM events WHERE seq=NEW.event_seq)!=(SELECT s.run_id FROM attempts a JOIN invocations i ON i.id=a.invocation_id JOIN spans s ON s.id=i.span_id WHERE a.id=NEW.attempt_id) BEGIN SELECT RAISE(ABORT,'cross-run check'); END;

CREATE TRIGGER recovery_run_scope BEFORE INSERT ON recovery_edges WHEN (SELECT s.run_id FROM attempts a JOIN invocations i ON i.id=a.invocation_id JOIN spans s ON s.id=i.span_id WHERE a.id=NEW.to_attempt_id)!=(SELECT s.run_id FROM attempts a JOIN invocations i ON i.id=a.invocation_id JOIN spans s ON s.id=i.span_id WHERE a.id=NEW.from_attempt_id) BEGIN SELECT RAISE(ABORT,'cross-run recovery'); END;

CREATE TRIGGER actor_span_scope BEFORE INSERT ON spans WHEN (SELECT project_id FROM actors WHERE id=NEW.actor_id)!=(SELECT se.project_id FROM runs r JOIN tasks t ON t.id=r.task_id JOIN sessions se ON se.id=t.session_id WHERE r.id=NEW.run_id) BEGIN SELECT RAISE(ABORT,'cross-project actor'); END;

CREATE TRIGGER event_actor_scope BEFORE INSERT ON events WHEN NEW.actor_id IS NOT NULL AND (SELECT project_id FROM actors WHERE id=NEW.actor_id)!=(SELECT se.project_id FROM runs r JOIN tasks t ON t.id=r.task_id JOIN sessions se ON se.id=t.session_id WHERE r.id=NEW.run_id) BEGIN SELECT RAISE(ABORT,'cross-project event actor'); END;

CREATE TRIGGER graph_version_scope BEFORE INSERT ON graph_versions WHEN NEW.previous_id IS NOT NULL AND (NEW.run_id!=(SELECT run_id FROM graph_versions WHERE id=NEW.previous_id) OR NEW.kind!=(SELECT kind FROM graph_versions WHERE id=NEW.previous_id)) BEGIN SELECT RAISE(ABORT,'graph revision scope'); END;

CREATE TRIGGER supersedes_scope BEFORE INSERT ON events WHEN NEW.supersedes_seq IS NOT NULL AND (NEW.supersedes_seq>=NEW.seq OR NEW.run_id!=(SELECT run_id FROM events WHERE seq=NEW.supersedes_seq)) BEGIN SELECT RAISE(ABORT,'invalid correction scope'); END;

CREATE TRIGGER graph_edges_graph_id_entity_run BEFORE INSERT ON graph_edges WHEN NEW.graph_id IS NOT NULL AND (SELECT run_id FROM events WHERE seq=NEW.event_seq)!=(SELECT run_id FROM graph_versions WHERE id=NEW.graph_id) BEGIN SELECT RAISE(ABORT,'cross-run entity'); END;

CREATE TRIGGER dag_transitions_span_id_entity_run BEFORE INSERT ON dag_transitions WHEN NEW.span_id IS NOT NULL AND (SELECT run_id FROM events WHERE seq=NEW.event_seq)!=(SELECT run_id FROM spans WHERE id=NEW.span_id) BEGIN SELECT RAISE(ABORT,'cross-run entity'); END;

CREATE TRIGGER obsidian_sync_graph_id_entity_run BEFORE INSERT ON obsidian_sync WHEN NEW.graph_id IS NOT NULL AND (SELECT run_id FROM events WHERE seq=NEW.event_seq)!=(SELECT run_id FROM graph_versions WHERE id=NEW.graph_id) BEGIN SELECT RAISE(ABORT,'cross-run entity'); END;

CREATE TRIGGER kv_operations_producer_span_id_entity_run BEFORE INSERT ON kv_operations WHEN NEW.producer_span_id IS NOT NULL AND (SELECT run_id FROM events WHERE seq=NEW.event_seq)!=(SELECT run_id FROM spans WHERE id=NEW.producer_span_id) BEGIN SELECT RAISE(ABORT,'cross-run entity'); END;

CREATE TRIGGER trajectory_steps_trajectory_id_entity_run BEFORE INSERT ON trajectory_steps WHEN NEW.trajectory_id IS NOT NULL AND (SELECT run_id FROM events WHERE seq=NEW.event_seq)!=(SELECT run_id FROM trajectories WHERE id=NEW.trajectory_id) BEGIN SELECT RAISE(ABORT,'cross-run entity'); END;

CREATE TRIGGER trajectory_steps_span_id_entity_run BEFORE INSERT ON trajectory_steps WHEN NEW.span_id IS NOT NULL AND (SELECT run_id FROM events WHERE seq=NEW.event_seq)!=(SELECT run_id FROM spans WHERE id=NEW.span_id) BEGIN SELECT RAISE(ABORT,'cross-run entity'); END;

CREATE TRIGGER rerank_candidates_trajectory_id_entity_run BEFORE INSERT ON rerank_candidates WHEN NEW.trajectory_id IS NOT NULL AND (SELECT run_id FROM events WHERE seq=NEW.event_seq)!=(SELECT run_id FROM trajectories WHERE id=NEW.trajectory_id) BEGIN SELECT RAISE(ABORT,'cross-run entity'); END;

CREATE TRIGGER hole_events_hole_id_entity_run BEFORE INSERT ON hole_events WHEN NEW.hole_id IS NOT NULL AND (SELECT run_id FROM events WHERE seq=NEW.event_seq)!=(SELECT run_id FROM holes WHERE id=NEW.hole_id) BEGIN SELECT RAISE(ABORT,'cross-run entity'); END;

CREATE TRIGGER objective_outcomes_check_id_run BEFORE INSERT ON objective_outcomes WHEN NEW.check_id IS NOT NULL AND (SELECT run_id FROM events WHERE seq=NEW.event_seq)!=(SELECT e.run_id FROM acceptance_checks t JOIN events e ON e.seq=t.event_seq WHERE t.id=NEW.check_id) BEGIN SELECT RAISE(ABORT,'cross-run fact'); END;

CREATE TRIGGER agent_leases_decision_id_run BEFORE INSERT ON agent_leases WHEN NEW.decision_id IS NOT NULL AND (SELECT run_id FROM events WHERE seq=NEW.event_seq)!=(SELECT e.run_id FROM meta_decisions t JOIN events e ON e.seq=t.event_seq WHERE t.id=NEW.decision_id) BEGIN SELECT RAISE(ABORT,'cross-run fact'); END;

CREATE TRIGGER lease_events_lease_id_run BEFORE INSERT ON lease_events WHEN NEW.lease_id IS NOT NULL AND (SELECT run_id FROM events WHERE seq=NEW.event_seq)!=(SELECT e.run_id FROM agent_leases t JOIN events e ON e.seq=t.event_seq WHERE t.id=NEW.lease_id) BEGIN SELECT RAISE(ABORT,'cross-run fact'); END;

