CREATE TRIGGER judge_results_check_id_run BEFORE INSERT ON judge_results WHEN NEW.check_id IS NOT NULL AND (SELECT run_id FROM events WHERE seq=NEW.event_seq)!=(SELECT e.run_id FROM acceptance_checks t JOIN events e ON e.seq=t.event_seq WHERE t.id=NEW.check_id) BEGIN SELECT RAISE(ABORT,'cross-run fact'); END;

